'use strict';
// The rocket DOM identifiers are retained for layout compatibility; new rounds are turn-based.
const exploration={stage:0,state:'idle',history:[],from:0,to:0,changed:0,id:null};
const previousRestore=restoreActive,previousSettlement=renderMarketSettlement,previousControls=updateAccountControls,previousPaint=paintRocket;
function explorationControls(){const a=accountProfile?.active,active=a?.kind==='explore',locked=!accountReady||accountBusy||!!pendingOperation;
 if(a?.kind==='rocket')return; // Let an already-running legacy round finish safely.
 $('rocketLaunch').textContent=accountBusy?'탐사 확인 중…':active?'다음 구역 탐사 · 성공률 80%':'탐사 시작 ↗';
 $('rocketLaunch').disabled=locked||!!a&&!active||!active&&save.gold<100;
 $('rocketCashout').textContent='귀환 · 보상 받기';$('rocketCashout').disabled=locked||!active;
 $('rocketBet').disabled=locked||!!a;document.querySelectorAll('[data-bet]').forEach(b=>b.disabled=locked||!!a);
 $('exploreRetry').hidden=!pendingOperation&&accountReady;
}
updateAccountControls=function(){previousControls();explorationControls()};
function setExploration(stage,state,id){exploration.from=exploration.to;exploration.to=stage;exploration.changed=rocketNow();exploration.stage=stage;exploration.state=state;exploration.id=id;rocket.state='idle'}
function resetExplorationDisplay(){setExploration(0,'idle',null);exploration.from=0;$('rocketCanvas').parentElement.classList.remove('crashed','collected');$('rocketPhase').textContent='탐사 대기';$('rocketMultiplier').textContent='1.00×';$('rocketPayout').textContent='0 G';$('rocketStatus').textContent='투입 골드를 정하고 새 탐사를 시작하세요.'}
restoreActive=function(){const a=accountProfile?.active;if(a?.kind!=='explore'){previousRestore();return}show('market');window.marketActive=false;selectMarketGame('rocket');setExploration(a.stage,'ready',a.id);rocketLock(true);$('rocketCanvas').parentElement.classList.remove('crashed','collected');$('rocketPhase').textContent=a.stage?'구역 '+a.stage+' / 10 · 탐사 성공':'출발 준비';$('rocketMultiplier').textContent=a.multiplier.toFixed(2)+'×';$('rocketPayout').textContent=Math.floor(a.bet*a.multiplier).toLocaleString()+' G';$('rocketStatus').textContent='귀환 보상은 확정 · 다음 구역 도전은 성공률 80%';$('rocketResult').textContent='제한시간이 없습니다. 천천히 선택하세요.';explorationControls()};
renderMarketSettlement=function(s){if(s?.kind!=='explore'){previousSettlement(s);explorationControls();return}window.marketActive=false;rocketLock(false);setExploration(s.stage,s.outcome,s.id);$('rocketCanvas').parentElement.classList.remove('crashed','collected');$('rocketCanvas').parentElement.classList.add(s.paid?'collected':'crashed');$('rocketPhase').textContent=s.outcome==='complete'?'10구역 탐사 완료':s.paid?'드론 귀환 완료':'드론 탐사 실패';$('rocketMultiplier').textContent=(s.multiplier||0).toFixed(2)+'×';$('rocketPayout').textContent=s.paid.toLocaleString()+' G';$('rocketStatus').textContent=s.paid?'보상이 보유 골드에 반영되었습니다.':'다음 구역 진입에 실패했습니다.';$('rocketResult').textContent=(s.stage?s.stage+'구역 성공':s.paid?'탐사 전 귀환':'첫 구역 진입 실패')+' · 귀환 보상 '+s.paid.toLocaleString()+' G';if(!exploration.history.some(h=>h.id===s.id))exploration.history.unshift(s);exploration.history.splice(10);$('rocketHistory').innerHTML=exploration.history.map(h=>'<span class="'+(h.paid?'success':'failure')+'">'+(h.stage?h.stage+'구역':h.paid?'출발 전 귀환':'첫 구역 실패')+' <small>'+h.paid.toLocaleString()+' G · '+(h.paid?'귀환':'실패')+'</small></span>').join('');if(s.paid)resetExplorationDisplay();renderMarket();explorationControls()};
async function explorationRequest(returning=false){if(accountBusy||pendingOperation||!accountReady)return;const a=accountProfile?.active;if(a?.kind==='rocket'){if(returning)return cashoutServer();return}if(a&&a.kind!=='explore')return;let action,fields;if(a){action=returning?'exploreReturn':'exploreStep';fields={activeId:a.id,stage:a.stage}}else{if(returning)return;const bet=Number($('rocketBet').value);if(!Number.isSafeInteger(bet)||bet<100||bet>100000)return toast('100~100,000 G를 입력하세요.');action='exploreStart';fields={bet}}exploration.state='pending';$('rocketStatus').textContent=returning?'귀환 보상을 확인하고 있습니다…':'탐사 결과를 확인하고 있습니다…';try{const r=await transact(action,fields);if(r){if(r.profile.active?.kind==='explore')restoreActive();else renderMarketSettlement(r.result.settlement||r.profile.lastSettlement)}else{$('rocketStatus').textContent=pendingOperation?'연결 확인 필요 · 같은 요청으로 다시 확인하세요.':'현재 탐사 상태를 다시 확인하세요.';exploration.state='waiting'}}finally{explorationControls()}}
$('rocketLaunch').onclick=()=>explorationRequest();$('rocketCashout').onclick=()=>explorationRequest(true);$('exploreRetry').onclick=syncAccount;
paintRocket=function(now){if(accountProfile?.active?.kind==='rocket'){previousPaint(now);return}if(view!=='market')return;const c=$('rocketCanvas').getContext('2d'),w=900,h=520;c.clearRect(0,0,w,h);c.fillStyle='#09171e';c.fillRect(0,0,w,h);for(let i=0;i<45;i++){c.fillStyle=i%4?'#294950':'#6a9992';c.fillRect(i*137%w,i*83%h,2,2)}const progress=Math.min(1,Math.max(0,(now-exploration.changed)/650)),position=exploration.from+(exploration.to-exploration.from)*(1-(1-progress)**3);c.strokeStyle='#345954';c.lineWidth=3;c.beginPath();c.moveTo(65,330);c.lineTo(830,330);c.stroke();for(let i=1;i<=10;i++){const x=65+(i-1)*85;c.fillStyle=i<=exploration.stage?'#c7f268':'#203b40';c.beginPath();c.arc(x,330,19,0,Math.PI*2);c.fill();c.fillStyle=i<=exploration.stage?'#14251c':'#9eb7b4';c.font='bold 15px sans-serif';c.textAlign='center';c.fillText(String(i),x,335)}const x=65+Math.max(0,position-1)*85,y=395+Math.sin(now/450)*5;if(assets.drone)c.drawImage(assets.drone,x-36,y-36,72,72);else{c.fillStyle='#7ce2d0';c.fillRect(x-23,y-12,46,24)}c.textAlign='center';c.fillStyle=exploration.state==='lost'?'#ff977c':'#bad5ce';c.font='18px sans-serif';};
explorationControls();
